def _fmt_rub(n) -> str:
    """1800 → '1 800'. Разделитель тысяч — неразрывный пробел не нужен (Telegram plain)."""
    try:
        return f"{int(round(float(n))):,}".replace(",", " ")
    except Exception:
        return str(n)

